INSERT INTO `candidates` (`id`, `student_id`, `description`, `score`, `color`, `is_disqualified`, `img`, `created_at`, `updated_at`) VALUES
(1, 247, '<div style=\"\"><span style=\"text-align: var(--bs-body-text-align);\">Visi</span></div><div><span style=\"line-height: 107%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Visi ini memang sengaja untuk dibuat seringkas-ringkasnya. Hal ini untuk\nmembuat mahasiswa mengingat dengan mudah visinya sehingga apabila disebutkan\n“Aksi Nyata dari stmik bandung&nbsp; untuk\nIndonesia” mahasiswa akan tahu dan mengenal bahwa kalimat ini ciri khas dari\nseorang Muhammad ikhwan. Walaupun simpel tetapi tidak dilupakan juga entitas\ndari visi ini yaitu dengan menuangkan langkah-langkah di misinya.</span><br></div><div><span style=\"line-height: 107%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br></span></div><div><span style=\"line-height: 107%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Misi</span></div><div><span style=\"line-height: 107%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><p class=\"MsoNoSpacing\"><span style=\"border: 1pt none windowtext; padding: 0cm;\">Membangun internal organisasi yang bersifat solid,\naktif, professional dan menyenangkan</span></p><p class=\"MsoNoSpacing\"><span style=\"text-align: var(--bs-body-text-align);\">Saya percaya bahwa kebaikan itu dimulai dari dalam. Bagaimana\ncaranya kita membangun bem stimik bandung yang terbaik tetapi internal\norganisasinya kacau. Oleh karena itu, membangun internal organisasi menjadi\nlangkah awal di dalam misi.</span></p><p class=\"MsoNoSpacing\"><span style=\"border: 1pt none windowtext; padding: 0cm;\"><b>Aktif, solutif dan kreatif dalam mengelola isu\nstrategis</b><o:p></o:p></span></p><p class=\"MsoNoSpacing\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Aktif kuliah dan berorganisasi. Aktif di setiap organisasi\natau kegiatan BEM yang diikuti . Solutif dalam pengertian mencari solusi dari\nberbagai isu secara bersama-sama dan diwujudkan secara nyata. Kreatif dengan\nmemberikan keleluasaan setiap bidang untuk mengembangkan kreatifitas dan\ninovatifitasnya.</span><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></span></p><p class=\"MsoNoSpacing\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p>&nbsp;</o:p></span></p><p class=\"MsoNormal\" style=\"margin: 3.75pt 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\"><span style=\"border: 1pt none windowtext; padding: 0cm;\"><b>Mewujudkan tata\nkelola organisasi yang tegas dan transparan</b></span><o:p></o:p></p><p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\">Transparan dari sumber dana sesuai dengan kondisi\nyang pantas diberikan kepada publik. Dalam hal ini kegiatan intern tingkat\nfakultas.<o:p></o:p></p><p class=\"MsoNoSpacing\"><o:p>&nbsp;</o:p></p><p class=\"MsoNoSpacing\"><o:p>&nbsp;</o:p></p><p class=\"MsoNoSpacing\"><b>Meningkatkan kedisiplinan dalam\nberbagai hal terutama kedisiplinan berorganisasi<o:p></o:p></b></p><p class=\"MsoNoSpacing\"><o:p><b>&nbsp;</b></o:p></p><p class=\"MsoNoSpacing\"><b>Mengadakan program yang mampu negasah\nbakat prestasi akademik mau pun non akademik<o:p></o:p></b></p><p class=\"MsoNoSpacing\"><o:p><b>&nbsp;</b></o:p></p><p class=\"MsoNormal\" style=\"margin: 3.75pt 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\"><b><span style=\"border: 1pt none windowtext; padding: 0cm;\">Meningkatkan iklim\nkolaboratif dan partisipatif untuk stimik bandung yang terbaik</span><o:p></o:p></b></p><p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\"><b>Permasalahan sekarang adalah organisasi yang ada di\nstimik bandung tidak memiliki dimensi, sehingga dapat dikatakan\norgansisasi&nbsp;<span style=\"border:none windowtext 1.0pt;mso-border-alt:\nnone windowtext 0cm;padding:0cm\">non-branded</span>. Organisasi di stimik\nbandung&nbsp; lebih mengutamakan organisasi\nmasing-masing, senat dengan senatnya, PH dengan PH nya dll. Tetapi jarang\nadanya sifat kolaboratif antar lembaga kemahasiswaan. Apabila sifat kolaboratif\nini tercapai, diharapkan adanya sikap kritis dari mahasiswa yang merupakan misi\nselanjutnya.<o:p></o:p></b></p><p class=\"MsoNoSpacing\"><o:p><b>&nbsp;</b></o:p></p><p class=\"MsoNormal\" style=\"margin: 3.75pt 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\"><span style=\"border: 1pt none windowtext; padding: 0cm;\"><b>Menjalin koordinasi dan kerjasama yang baik dengan\nsemua unsur internal maupun eksternal stimik bandung </b></span><o:p></o:p></p><p class=\"MsoNoSpacing\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; vertical-align: baseline;\">Koordinasi dan\nkerjasama baik secara internal dan eksternal dalam hal ini adalah koordinasi\nyang se-lini dengan organisasi internal di stimik bandung dan fakultas atau\nuniversitas lainya<span style=\"font-size:10.5pt;mso-fareast-font-family:\n&quot;Times New Roman&quot;;mso-bidi-font-family:Calibri;mso-bidi-theme-font:minor-latin;\nmso-fareast-language:EN-ID\"><o:p></o:p></span></p></span></div>', 1, '193, 11, 11', 0, 'ikhwan.png', '2022-02-22 23:03:23', '2022-02-23 09:36:41'),
(2, 406, '<h3 style=\"text-align: center;\"><span style=\"color: inherit; font-family: inherit; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><b>Visi</b></span></h3><div><p class=\"MsoListParagraphCxSpFirst\" style=\"\"><ol><li><span lang=\"EN-US\" style=\"\">Menjadikan\nBEM yang berakhlak mulia.</span></li><li><span lang=\"EN-US\" style=\"\">Menjadikan\nBEM sebagai Lembaga interaktif kepada mahasiswa dan masyarakat untuk bersinergi\ndalam menciptakan inovasi (WADAH) Inspirasi untuk memajukan BEM maupun kampus.</span></li><li><span lang=\"EN-US\" style=\"\">Mewujudkan\nBEM yang professional berdasarkan budaya dan teknologi</span></li></ol><div></div></p><span style=\"color: inherit; font-family: inherit; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><div style=\"text-align: center;\"><span style=\"color: inherit; font-family: inherit; font-size: var(--bs-body-font-size); text-align: var(--bs-body-text-align);\"><b>“Belajar dari kegagalan adalah hal yang bijak.”</b></span></div></span><p class=\"trt0xe\" align=\"center\" style=\"text-align: left; margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></p><p class=\"trt0xe\" align=\"center\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br></p><h3 style=\"text-align: center; margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><b>Misi</b></h3><p class=\"trt0xe\" align=\"center\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br></p><p class=\"trt0xe\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><ol><li>Membangun kontribusi dari peran aktif mahasiswa STMIK Bandung.</li><li>Mempromosikan sinergi 0mahasiswa STMIK sesuai dengan minat dan\nbakat mahasiswa STMIK Bandung.</li><li>Membangun lingkungan internal yang solid dan apresiatif sebagai\nupaya peningkatan peran dan fungsi sumber daya organisasi.</li><li>Menghadirkan partisipasi minat dan bakat mahasiswa yang\nsupraktif dan apresiatif.</li></ol><o:p></o:p></p><p class=\"trt0xe\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></p><p class=\"trt0xe\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></p><p class=\"trt0xe\" align=\"center\" style=\"margin: 0cm 0cm 3pt 36pt; text-align: center; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">\n\n\n\n\n\n</p><p class=\"trt0xe\" style=\"margin: 0cm 0cm 3pt 36pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><br></p></div>', 4, '20, 134, 255', 0, 'rivan.png', '2022-02-22 23:07:42', '2022-02-24 02:44:57'),
(3, 382, '<h3 style=\"text-align: center;\"><span style=\"text-align: var(--bs-body-text-align);\">Visi dan Misi</span></h3><div><p class=\"MsoNormal\" align=\"center\" style=\"\"><span lang=\"EN-US\">BADAN\nEKSEKUTIF MAHASISWA (BEM) STMIK BANDUNG<o:p></o:p></span></p><p class=\"MsoNormal\" align=\"center\" style=\"\"><b>Visi</b></p><p class=\"MsoNormal\" style=\"\"><span lang=\"EN-US\">Menjadi BEM STMIK\nBandung sebagai tempat pembinaan untuk melahirkan kader kader yang berkualitas\ndan tempat berkarya bagi seluruh mahasiswa/I, dan tentunya akan menjadi sebuah\nlembaga yang edukatif, solitif, dinamis, kritis dan aktualis yang dilandasi\noleh pancasila serta berbudi pekerti luhur untuk menjadi insan penerus bangsa\nyang cerdas.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"\"><br></p><p class=\"MsoNormal\" style=\"text-align: center;\"><b>Misi</b></p><p class=\"MsoListParagraphCxSpFirst\" style=\"\"><ol><li><span lang=\"EN-US\">Membentuk struktur BEM STMIK\nBandung yang kokoh</span></li><li><span lang=\"EN-US\">Menumbuhkan kesolidan,\nkedisiplinan, toleransi antara Mahasiswa/I</span></li><li>Mengadakan kegiatan untuk meningkatakan soft skill Mahasiswa/I</li><li>Mengembangkan, dan menyelenggarakan program kegiatan kemahasiswaan\nyang berdasarkan dan berpihak kepada kesejahteraan Mahasiswa baik secara\njasmani maupun Rohani</li><li>Mengefektifkan dan serta menggali, membina, menampung, menyalurkan\npotensi / bakat Mahasiswa melalui pembentukan, kerjasama serta pengembangan\nUnit Kegiatan Mahasiswa (UKM) yang terintegrasi dan terkontrol secara\nsistematis yang menyangkut akademis maupun non akademis</li><li>Menjalin kerja sama yang baik dan optimal dengan himpunan mahasiswa\nJurusan (HMJ) sebagai lembaga basis ditingkat maisng-masing jurusan yang\nbertugas penyerapan aspirasi mahasiswa/I secara umum</li><li>Memberikan\nApresiasi/Penghargaan kepada Mahasasiswa/I yang berprestasi dan mengharumkan\nnama institusi baik ditingkat lokal, Nasional bahakan Internasional, baik\nperorangan maupun kelompok.</li></ol></p></div>', 1, '61, 255, 119', 0, 'saikun.png', '2022-02-22 23:11:19', '2022-02-23 09:38:27');
